    // C(J+11)=H(I+12) -> (5,2)
    // C(J+12)=H(I+8) -> (6,2)
    // C(J+13)=H(I+12) -> (1,3)
    // C(J+15)=H(I+4) -> (3,3)
    // C(J+16)=H(I+8) -> (4,3)
